DROP TABLE IF EXISTS `improvement_pairs`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!40101 SET character_set_client = utf8 */;
CREATE TABLE `improvement_pairs` (
  `id` int(10) unsigned NOT NULL AUTO_INCREMENT,
  `submission_id_a` int(10) unsigned NOT NULL,
  `submission_id_b` int(10) unsigned NOT NULL,
  `delta_score` double NOT NULL,
  `created_at` timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP,
  PRIMARY KEY (`id`),
  UNIQUE KEY `uniq_pair` (`submission_id_a`,`submission_id_b`),
  KEY `idx_created_at` (`created_at`),
  KEY `improvement_pairs_ibfk_2` (`submission_id_b`),
  CONSTRAINT `improvement_pairs_ibfk_1` FOREIGN KEY (`submission_id_a`) REFERENCES `submissions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `improvement_pairs_ibfk_2` FOREIGN KEY (`submission_id_b`) REFERENCES `submissions` (`id`) ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB AUTO_INCREMENT=112821 DEFAULT CHARSET=latin1;
